package com.secureshop.app.controller; import java.util.*; import org.springframework.web.bind.annotation.*; import com.secureshop.app.model.*; import com.secureshop.app.service.*; @RestController @RequestMapping("/api") public class ShopController { private final ProductService s; public ShopController(ProductService s){this.s=s;} @GetMapping("/products") public List<Product> all(){return s.all();} @GetMapping("/products/{id}") public Product one(@PathVariable Long id){return s.byId(id);} }
